// Targeted search: rounding at precision P only changes if the two candidate
// values straddle a tie boundary B = (2k+1)/(2*10^P). Enumerate boundaries.
fn nextafter_up(v: f32) -> f32 { f32::from_bits(v.to_bits() + 1) }
fn nextafter_dn(v: f32) -> f32 { f32::from_bits(v.to_bits() - 1) }

fn scan(p: usize) -> Vec<(u32, f32, String, String)> {
    let scale = 10f64.powi(p as i32);
    let mut out = Vec::new();
    let kmax = (100.0 * scale) as u64;
    for k in 0..kmax {
        let b = (2 * k + 1) as f64 / (2.0 * scale); // tie boundary in percent-space
        let v0 = (b / 100.0) as f32;
        let mut cands = vec![v0];
        let mut u = v0; let mut d = v0;
        for _ in 0..3 { u = nextafter_up(u); d = nextafter_dn(d); cands.push(u); cands.push(d); }
        for v in cands {
            if !(v >= 0.0 && v <= 1.0) { continue; }
            let a = format!("{:.*}", p, (v * 100.0f32) as f64);   // C++ / mulss
            let c = format!("{:.*}", p, (v as f64) * 100.0f64);   // promote-then-mul
            if a != c { out.push((v.to_bits(), v, a, c)); if out.len() >= 8 { return out; } }
        }
    }
    out
}
fn main() {
    for p in [1usize, 2, 3, 4] {
        println!("== precision {} : mulss(f32) vs promote-then-mul(f64) ==", p);
        let r = scan(p);
        if r.is_empty() { println!("   no divergence found among tie-boundary candidates"); }
        for (bits, v, a, c) in r {
            println!("   v_bits={:#010x}  v(exact)={:.30}", bits, v);
            println!("       C++ mulss path -> [{}%]   promote-then-mul -> [{}%]", a, c);
        }
    }
}
